from typing import List

def min_slides(grid: List[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    dp = [[float('inf')] * cols for _ in range(rows)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                dp[i][j] = 0
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if is_valid(nx, ny) and dp[nx][ny] > dp[x][y] + 1:
                            dp[nx][ny] = dp[x][y] + 1
                            stack.append((nx, ny))

    return min(dp[row][-1] for row in dp)
```

