from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    start = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
                break
        if start:
            break

    queue = deque([(start, False, 0)])
    visited = set()
    visited.add(start)

    while queue:
        (x, y), broken, steps = queue.popleft()

        if grid[x][y] == 'E':
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if is_valid(nx, ny) and (nx, ny) not in visited:
                if grid[nx][ny] == '1' and not broken:
                    queue.append(((nx, ny), True, steps + 1))
                    visited.add((nx, ny))
                elif grid[nx][ny] != '1':
                    queue.append(((nx, ny), broken, steps + 1))
                    visited.add((nx, ny))

    return -1
