def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows or not aligns:
        return ""

    num_cols = len(rows[0])
    if any(len(row) != num_cols for row in rows):
        raise ValueError("All rows must have the same number of columns")

    col_widths = [max(len(cell) for cell in column) for column in zip(*rows)]

    formatted_rows = []
    for row, align in zip(rows, aligns):
        formatted_row = []
        for cell, width, align_char in zip(row, col_widths, align):
            if align_char == 'l':
                formatted_cell = f"{cell:<{width}}"
            elif align_char == 'r':
                formatted_cell = f"{cell:>{width}}"
            else:
                formatted_cell = f"{cell:^{width}}"
            formatted_row.append(formatted_cell)
        formatted_rows.append("|".join(formatted_row))

    header = "|".join(f"{'':<{col_width}}" for _ in range(num_cols))
    separator = "+".join("-" * (width + 2) for width in col_widths)

    return "\n".join([header, separator] + formatted_rows + [separator])
