def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    for instruction in program:
        parts = instruction.split()
        if parts[0] == 'PUSH':
            stack.append(int(parts[1]))
        elif parts[0] == 'POP':
            if stack:
                stack.pop()
            else:
                return None
        elif parts[0] == 'ADD':
            if len(stack) >= 2:
                stack.append(stack.pop() + stack.pop())
            else:
                return None
        elif parts[0] == 'SUB':
            if len(stack) >= 2:
                stack.append(-stack.pop() + stack.pop())
            else:
                return None
        elif parts[0] == 'MUL':
            if len(stack) >= 2:
                stack.append(stack.pop() * stack.pop())
            else:
                return None
        elif parts[0] == 'DIV':
            if len(stack) >= 2 and stack[-1] != 0:
                stack.append(int(stack.pop() / stack.pop()))
            else:
                return None
        elif parts[0] == 'MOD':
            if len(stack) >= 2:
                stack.append(stack.pop() % stack.pop())
            else:
                return None
        elif parts[0] == 'DUP':
            if stack:
                stack.append(stack[-1])
            else:
                return None
        elif parts[0] == 'SWAP':
            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
            else:
                return None
        elif parts[0] == 'PRINT':
            if stack:
                print(stack[-1])
            else:
                return None
        elif parts[0] == 'EXIT':
            break
    return stack
