    for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
        if board[i][j] == 1:
            return False
    for i, j in zip(range(row, n, 1), range(col, -1, -1)):
        if board[i][j] == 1:
            return False
    return True

def solve_n_queens_util(board: List[List[int]], col: int, blocked: Set[Tuple[int, int]], res: int) -> int:
    n = len(board)
    if col >= n:
        return 1

    count = 0
    for i in range(n):
        if (i, col) not in blocked and is_safe(board, i, col):
            board[i][col] = 1
            count += solve_n_queens_util(board, col + 1, blocked, res)
            board[i][col] = 0

    return count

