from typing import List

def matrix_power_mod(matrix: List[List[int]], exp: int, mod: int) -> List[List[int]]:
    def multiply_matrices(a: List[List[int]], b: List[List[int]]) -> List[List[int]]:
        result = [[0 for _ in range(len(b[0]))] for _ in range(len(a))]
        for i in range(len(a)):
            for j in range(len(b[0])):
                for k in range(len(b)):
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
        return result

    def matrix_power(mat: List[List[int]], n: int) -> List[List[int]]:
        if n == 1:
            return mat
        elif n % 2 == 0:
            half_power = matrix_power(mat, n // 2)
            return multiply_matrices(half_power, half_power)
        else:
            return multiply_matrices(mat, matrix_power(mat, n - 1))

    return matrix_power(matrix, exp)
