def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]:
    order_counts = defaultdict(int)
    pending_orders = []

    for event_type, product_id, quantity in events:
        if event_type == 'order':
            order_counts[product_id] += quantity
        elif event_type == 'cancel':
            if product_id in order_counts:
                if order_counts[product_id] > quantity:
                    order_counts[product_id] -= quantity
                else:
                    del order_counts[product_id]
        elif event_type == 'pending':
            pending_orders.append((product_id, quantity))

    return dict(order_counts), pending_orders
