from collections import deque

def flatten_list(nested: list) -> list:
    flat_list = []
    queue = deque([nested])

    while queue:
        current_element = queue.popleft()
        if isinstance(current_element, list):
            queue.extendleft(reversed(current_element))
        else:
            flat_list.append(current_element)

    return flat_list
```

