    k = len(b)
    n = len(b[0])

    # Inicializar la matriz resultante con ceros
    result = [[0 for _ in range(n)] for _ in range(m)]

    # Realizar la multiplicación matricial
    for i in range(m):
        for j in range(n):
            for l in range(k):
                result[i][j] += a[i][l] * b[l][j]

    return result

