def is_host_reachable(host: str) -> bool:
    try:
        # Ejecutar el comando ping con -c 1
        result = subprocess.run(['ping', '-c', '1', host], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        # Comprobar si el comando terminó con estado 0 (éxito)
        return result.returncode == 0
    except Exception as e:
        print(f"Error al ejecutar el comando ping: {e}")
        return False

