def caesar_cipher(text: str, shift: int) -> str:
    result = []
    for char in text:
        if char.isalpha():
            base = 'A' if char.isupper() else 'a'
            shifted = chr((ord(char) - ord(base) + shift) % 26 + ord(base))
            result.append(shifted)
        else:
            result.append(char)
    return ''.join(result)
