def smallest_lcs(a: str, b: str) -> str:
    m, n = len(a), len(b)
    dp = [["" for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + a[i - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs = dp[m][n]
    result = []

    def backtrack(i, j):
        while i > 0 and j > 0:
            if a[i - 1] == b[j - 1]:
                result.append(a[i - 1])
                i -= 1
                j -= 1
            elif len(dp[i - 1][j]) > len(dp[i][j - 1]):
                i -= 1
            else:
                j -= 1

    backtrack(m, n)
    result.reverse()

    return ''.join(result)
