@lru_cache(None)
def lcs(a: str, b: str) -> str:
    if not a or not b:
        return ""
    elif a[-1] == b[-1]:
        return lcs(a[:-1], b[:-1]) + a[-1]
    else:
        return max(lcs(a, b[:-1]), lcs(a[:-1], b), key=len)

