from functools import lru_cache

def smallest_lcs(a: str, b: str) -> str:
    @lru_cache(None)
    def lcs(i, j):
        if i == len(a) or j == len(b):
            return ""
        elif a[i] == b[j]:
            return a[i] + lcs(i + 1, j + 1)
        else:
            return max(lcs(i + 1, j), lcs(i, j + 1), key=len)

    def lexicographically_smallest(s1, s2):
        for c1, c2 in zip(s1, s2):
            if c1 != c2:
                return c1 < c2
        return len(s1) < len(s2)

    result = set()
    @lru_cache(None)
    def backtrack(i, j, path):
        if i == len(a) or j == len(b):
            result.add(path)
            return
        if a[i] == b[j]:
            backtrack(i + 1, j + 1, path + a[i])
        backtrack(i + 1, j, path)
        backtrack(i, j + 1, path)

    backtrack(0, 0, "")

    return min(result, key=lambda x: (len(x), x))

# Example usage:
print(smallest_lcs("abcde", "ace"))  # Output: "ace"
print(smallest_lcs("abcdef", "zabcf"))  # Output: "bcf"
print(smallest_lcs("abc", "def"))  # Output: ""
