from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    start, end = None, None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    def bfs(start, break_allowed):
        queue = deque([start])
        visited = set([start])
        steps = 0

        while queue:
            for _ in range(len(queue)):
                x, y = queue.popleft()

                if (x, y) == end:
                    return steps

                for dx, dy in directions:
                    nx, ny = x + dx, y + dy

                    if 0 <= nx < rows and 0 <= ny < cols and (nx, ny) not in visited:
                        if grid[nx][ny] != '#' or break_allowed:
                            visited.add((nx, ny))
                            queue.append((nx, ny))

            steps += 1
            break_allowed = False

    return bfs(start, True)

