from collections import defaultdict, deque

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    queue = deque([(source, 1)])
    visited[source] = True

    path_count = 0

    while queue:
        node, paths = queue.popleft()

        if node == target:
            path_count += paths

        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append((neighbor, paths))

    return path_count
