from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    start, end = None, None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    queue = deque([(start, False)])
    visited = set()
    visited.add(start)

    while queue:
        (r, c), has_broken = queue.popleft()

        if (r, c) == end:
            return 0

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if is_valid(nr, nc):
                if grid[nr][nc] == '.' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), has_broken))
                elif grid[nr][nc] == '#' and not has_broken:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), True))

    return -1
