import operator
import re

def evaluate_expression(expression: str) -> float:
    operators = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '**': operator.pow,
        '-': operator.neg
    }

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '-':
            values.append(-right)
        else:
            values.append(operator(left, right))

    def greater_precedence(op1, op2):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}
        return precedence[op1] > precedence[op2]

    tokens = re.findall(r'\d+\.\d+|\d+|\(|\)|\+|-|\*|/|\*\*', expression)
    values = []
    ops = []

    for token in tokens:
        if token.isdigit() or '.' in token:
            values.append(float(token))
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                apply_operator(ops, values)
            ops.pop()
        else:
            while (ops and ops[-1] != '(' and
                   greater_precedence(ops[-1], token)):
                apply_operator(ops, values)
            ops.append(token)

    while ops:
        apply_operator(ops, values)

    if len(values) != 1:
        raise ValueError("Invalid expression")

    return values[0]

# Example usage:
try:
    result = evaluate_expression("3 + 5 * (2 - 8)")
    print(result)  # Output: -26.0
except Exception as e:
    print(e)
