        if col >= n:
            return 1
        count = 0
        for i in range(n):
            if (i, col) not in blocked and is_safe(board, i, col):
                board[i][col] = 'Q'
                count += solve(board, col + 1)
                board[i][col] = '.'
        return count

    board = [['.' for _ in range(n)] for _ in range(n)]
    return solve(board, 0)
