        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False
        return True

    def solve(board, col):
        if col >= n:
            return 1
        count = 0
        for i in range(n):
            if (i, col) not in blocked and is_safe(board, i, col):
                board[i][col] = 1
                count += solve(board, col + 1)
                board[i][col] = 0
        return count

    board = [[0 for _ in range(n)] for _ in range(n)]
    return solve(board, 0)

