    def multiply_mod(a: list[list[int]], b: list[list[int]], mod: int) -> list[list[int]]:
        n = len(a)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
        return result

    def matrix_pow(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
        if exp == 0:
            n = len(matrix)
            return [[int(i == j) for j in range(n)] for i in range(n)]
        elif exp == 1:
            return [row[:] for row in matrix]
        else:
            half_pow = matrix_pow(matrix, exp // 2, mod)
            result = multiply_mod(half_pow, half_pow, mod)
            if exp % 2 == 1:
                result = multiply_mod(result, matrix, mod)
            return result

    return matrix_pow(matrix, exp, mod)
