from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    start, end = None, None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if not start or not end:
        return -1

    queue = deque([(start, False, 0)])  # (position, has_broken_wall, steps)
    visited = set()
    visited.add((start, False))

    while queue:
        (x, y), has_broken_wall, steps = queue.popleft()

        if (x, y) == end:
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '.' and (nx, ny, has_broken_wall) not in visited:
                    queue.append(((nx, ny), has_broken_wall, steps + 1))
                    visited.add(((nx, ny), has_broken_wall))
                elif grid[nx][ny] == '#' and not has_broken_wall and (nx, ny, True) not in visited:
                    queue.append(((nx, ny), True, steps + 1))
                    visited.add(((nx, ny), True))

    return -1
