from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    def bfs(start, break_wall=False):
        queue = deque([(start, 0)])
        visited = set([start])

        while queue:
            (x, y), steps = queue.popleft()

            if (x, y) == end:
                return steps

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if 0 <= nx < rows and 0 <= ny < cols and (nx, ny) not in visited:
                    if grid[nx][ny] == '.' or (grid[nx][ny] == '#' and break_wall):
                        visited.add((nx, ny))
                        queue.append(((nx, ny), steps + 1))
                    elif grid[nx][ny] == '#':
                        visited.add((nx, ny))
                        queue.append(((nx, ny), steps + 2))

        return float('inf')

    min_steps = min(bfs(start), bfs(start, break_wall=True))
    return min_steps if min_steps != float('inf') else -1
