import re

def identifier_to_snake(name: str) -> str:
    # Split on underscores and hyphens, ignoring empty pieces
    parts = [part for part in re.split(r'[_-]+', name) if part]

    snake_case_parts = []
    for part in parts:
        new_part = ''
        i = 0
        while i < len(part):
            if i + 1 < len(part) and part[i].islower() and part[i+1].isupper():
                new_part += part[i:i+2].lower()
                i += 2
            elif part[i].isalpha() or part[i].isdigit():
                new_part += part[i].lower()
                i += 1
            else:
                i += 1
        snake_case_parts.append(new_part)

    return '_'.join(snake_case_parts)
