def decode_runs(encoded: str) -> str:
    decoded = []
    i = 0
    while i < len(encoded):
        char = encoded[i]
        if char == '\\':
            i += 1
            char = encoded[i]
        count = 1
        if i + 1 < len(encoded) and encoded[i + 1] == '~':
            i += 2
            while i < len(encoded) and encoded[i].isdigit():
                count *= 10
                count += int(encoded[i])
                i += 1
        decoded.append(char * count)
    return ''.join(decoded)
