from typing import List, Tuple

def is_safe(board: List[List[int]], row: int, col: int, n: int, blocked: Set[Tuple[int, int]]) -> bool:
    for i in range(col):
        if board[row][i] == 1 or (row, i) in blocked:
            return False

    for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
        if board[i][j] == 1 or (i, j) in blocked:
            return False

    for i, j in zip(range(row, n, 1), range(col, -1, -1)):
        if board[i][j] == 1 or (i, j) in blocked:
            return False

    return True

def solve_n_queens_util(board: List[List[int]], col: int, n: int, blocked: Set[Tuple[int, int]], res: List[int]) -> None:
    if col >= n:
        res.append(1)
        return

    for i in range(n):
        if is_safe(board, i, col, n, blocked):
            board[i][col] = 1
            solve_n_queens_util(board, col + 1, n, blocked, res)
            board[i][col] = 0

def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    board = [[0 for _ in range(n)] for _ in range(n)]
    blocked_set = set(blocked)
    res = []
    solve_n_queens_util(board, 0, n, blocked_set, res)
    return sum(res)

# Example usage:
print(count_queens(4, [(0, 0), (3, 2)]))  # Output should be the number of valid placements
