from collections import defaultdict, deque

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    graph = defaultdict(list)
    in_degree = [0] * n

    for u, v in pairs:
        graph[u].append(v)
        in_degree[v] += 1

    queue = deque([u for u in range(n) if in_degree[u] == 0])
    result = []

    while queue:
        if len(queue) > 1:
            return []  # Cycle detected

        u = queue.popleft()
        result.append(u)

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result) != n:
        return []  # Cycle detected or not all nodes were processed

    return result
