from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    queue = deque([(start, False)])
    visited = set()
    visited.add(start)

    steps = 0
    while queue:
        for _ in range(len(queue)):
            (x, y), broke_wall = queue.popleft()
            if (x, y) == end:
                return steps

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny):
                    if grid[nx][ny] == '.' and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        queue.append(((nx, ny), broke_wall))
                    elif grid[nx][ny] == '#' and not broke_wall:
                        visited.add((nx, ny))
                        queue.append(((nx, ny), True))

        steps += 1

    return -1
