from typing import List

def pack_bins(sizes: List[int], capacity: int) -> List[List[int]]:
    if any(size > capacity for size in sizes):
        raise ValueError("One or more items are larger than the bin capacity.")

    bins = []
    current_bin = []
    remaining_capacity = capacity

    for size in sorted(sizes, reverse=True):
        if size <= remaining_capacity:
            current_bin.append(size)
            remaining_capacity -= size
        else:
            bins.append(current_bin)
            current_bin = [size]
            remaining_capacity = capacity - size

    if current_bin:
        bins.append(current_bin)

    return bins
