from math import gcd
from functools import reduce

def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def chinese_remainder_theorem(a: list[int], n: list[int]) -> tuple[int, int]:
        sum = 0
        prod = reduce(lcm, n)
        for n_i, a_i in zip(n, a):
            p = prod // n_i
            sum += a_i * pow(p, -1, n_i) * p
        return (sum % prod, prod)

    a = [r % m for r, m in congruences]
    n = [m for _, m in congruences]

    result = chinese_remainder_theorem(a, n)
    if result[0] < 0:
        result = (result[0] + result[1], result[1])

    return result
