        prod = reduce(lcm, n)
        for n_i, a_i in zip(n, a):
            p = prod // n_i
            sum += a_i * mod_inverse(p, n_i) * p
        return sum % prod, prod

    a = [r % m for r, m in congruences]
    n = [m for _, m in congruences]

    try:
        x, L = chinese_remainder_theorem(a, n)
        return (x, L)
    except ValueError:
