from math import gcd
from functools import reduce

def lcm(a: int, b: int) -> int:
    return abs(a * b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def combine(pair1: tuple[int, int], pair2: tuple[int, int]) -> tuple[int, int]:
        r1, m1 = pair1
        r2, m2 = pair2
        M = m1 * m2
        s = (r2 - r1) % M
        t = m2
        while s != 0:
            quotient, remainder = divmod(t, s)
            t, s = s, remainder
        if t != 1:
            return None
        k = (s * r1 + t * r2) % M
        return (k, M)

    result = reduce(combine, congruences)
    if result is None:
        return None
    x, L = result
    return (x % L, L)
