from typing import List, Tuple
import math

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def lcm(a: int, b: int) -> int:
    return abs(a * b) // gcd(a, b)

def solve_congruences(congruences: List[Tuple[int, int]]) -> Tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    x, M = 0, 1

    for r, m in congruences:
        g = gcd(M, m)
        if (r % g) != (x % g):
            return None

        p, q = M // g, m // g
        x += r * p * pow(q, -1, g)
        M *= q

    return (x % M, M)
