from typing import List

def pack_bins(sizes: List[int], capacity: int) -> List[List[int]]:
    if any(size > capacity for size in sizes):
        raise ValueError("One or more items exceed the bin capacity.")

    bins = []
    sizes.sort(reverse=True)

    for size in sizes:
        placed = False
        for bin_ in bins:
            if sum(bin_) + size <= capacity:
                bin_.append(size)
                placed = True
                break
        if not placed:
            bins.append([size])

    return bins
