import operator

def evaluate_expression(expression: str) -> float:
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '**': operator.pow,
    }

    def parse(tokens):
        values = []
        ops_stack = []

        for token in tokens:
            if token.isdigit() or '.' in token:
                values.append(float(token))
            elif token == '(':
                ops_stack.append(token)
            elif token == ')':
                while ops_stack and ops_stack[-1] != '(':
                    apply_operator(values, ops_stack)
                ops_stack.pop()
            else:
                while (ops_stack and ops[token] <= ops.get(ops_stack[-1], 0)):
                    apply_operator(values, ops_stack)
                ops_stack.append(token)

        while ops_stack:
            apply_operator(values, ops_stack)

        return values[0]

    def apply_operator(values, ops_stack):
        op = ops_stack.pop()
        right = values.pop()
        left = values.pop()
        result = ops[op](left, right)
        values.append(result)

    try:
        tokens = expression.replace(' ', '').split(',')
        return parse(tokens)
    except Exception as e:
        raise ValueError("Invalid expression") from e
