def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    rows, cols = len(grid), len(grid[0])
    while True:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] > 3:
                    changed = True
                    grid[r][c] -= 4
                    if r > 0:
                        grid[r-1][c] += 1
                    if r < rows - 1:
                        grid[r+1][c] += 1
                    if c > 0:
                        grid[r][c-1] += 1
                    if c < cols - 1:
                        grid[r][c+1] += 1
        if not changed:
            break

    return grid
