from math import gcd
from functools import reduce

def lcm(a: int, b: int) -> int:
    return abs(a * b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def chinese_remainder_theorem(a: list[int], n: list[int]) -> tuple[int, int]:
        sum = 0
        prod = reduce(lcm, n)
        for n_i, a_i in zip(n, a):
            p = prod // n_i
            sum += a_i * mod_inverse(p, n_i) * p
        return sum % prod, prod

    a = [r % m for r, m in congruences]
    n = [m for _, m in congruences]

    try:
        return chinese_remainder_theorem(a, n)
    except ValueError:
        return None

def mod_inverse(a: int, m: int) -> int:
    m0, x0, x1 = m, 0, 1
    if m == 1:
        raise ValueError("Inverse doesn't exist")
    while a > 1:
        # q is quotient
        q = a // m
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0
    # Make x1 positive
    if x1 < 0:
        x1 += m0
    return x1
