def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    distance = [-1] * n
    parent = [-1] * n

    queue = deque([source])
    visited[source] = True
    distance[source] = 0

    while queue:
        current = queue.popleft()

        for neighbor in graph[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                distance[neighbor] = distance[current] + 1
                parent[neighbor] = current
                queue.append(neighbor)
            elif distance[neighbor] == distance[current] + 1 and parent[neighbor] != current:
                continue
            else:
                return 0

    if distance[target] == -1:
        return 0

    path_count = 0
    stack = []
    current = target
    while current != -1:
        stack.append(current)
        current = parent[current]

    while len(stack) > 1:
        node = stack.pop()
        if any(neighbor == stack[-1] for neighbor in graph[node]):
            path_count += 1

    return path_count + 1

