from typing import List, Tuple

def is_safe(board: List[List[int]], row: int, col: int, n: int) -> bool:
    for i in range(col):
        if board[row][i] == 1:
            return False

    for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
        if board[i][j] == 1:
            return False

    for i, j in zip(range(row, n, 1), range(col, -1, -1)):
        if board[i][j] == 1:
            return False

    return True

def solve_n_queens_util(board: List[List[int]], col: int, n: int, blocked: set[Tuple[int, int]]) -> int:
    if col >= n:
        return 1

    count = 0
    for i in range(n):
        if (i, col) not in blocked and is_safe(board, i, col, n):
            board[i][col] = 1
            count += solve_n_queens_util(board, col + 1, n, blocked)
            board[i][col] = 0

    return count

def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    if n == 0:
        return 1

    board = [[0 for _ in range(n)] for _ in range(n)]
    blocked_set = {(r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n}

    return solve_n_queens_util(board, 0, n, blocked_set)
