def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if any(size > capacity for size in sizes):
        raise ValueError("One or more items are larger than the bin capacity.")

    bins = []
    sizes.sort(reverse=True)

    for size in sizes:
        placed = False
        for bin_ in bins:
            if sum(bin_) + size <= capacity:
                bin_.append(size)
                placed = True
                break
        if not placed:
            bins.append([size])

    return bins
