from typing import List

def stabilize_sandpile(grid: List[List[int]]) -> List[List[int]]:
    if not grid or not grid[0]:
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while True:
        stable = True
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] > 3:
                    stable = False
                    grid[r][c] -= 4
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            grid[nr][nc] += 1

        if stable:
            break

    return grid
