def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def topple(r, c):
        if grid[r][c] < 4:
            return False
        grid[r][c] -= 4
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                grid[nr][nc] += 1
        return True

    changed = True
    while changed:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if topple(r, c):
                    changed = True

    return grid
