def lcm(a: int, b: int) -> int:
    return abs(a * b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    total_lcm = 1
    x = 0

    for r, m in congruences:
        if m == 0:
            continue

        # Find the modular inverse of m modulo L' (where L' is the product of all other moduli)
        L_prime = total_lcm // m
        inv = pow(L_prime, -1, m)

        # Update x and total_lcm
        x += r * L_prime * inv
        total_lcm *= m

    # Reduce x to be within the range [0, total_lcm)
    x %= total_lcm

    # Check if there is a solution by verifying all congruences
    for r, m in congruences:
        if x % m != r % m:
            return None

    return (x, total_lcm)
