import re

def identifier_to_snake(name: str) -> str:
    # Replace hyphens with underscores
    name = name.replace('-', '_')

    # Split on underscores and filter out empty strings
    parts = [part for part in name.split('_') if part]

    snake_case_parts = []
    for i, part in enumerate(parts):
        if i == 0:
            snake_case_parts.append(part)
        else:
            prev_part = parts[i-1]
            new_part = ''
            j = 0
            while j < len(part):
                if j + 1 < len(part) and part[j].islower() and part[j+1].isupper():
                    new_part += part[j] + '_'
                    j += 2
                elif j + 1 < len(part) and part[j].isalpha() and part[j+1].isdigit():
                    new_part += part[j] + '_'
                    j += 2
                elif j + 1 < len(part) and part[j].isdigit() and part[j+1].isalpha():
                    new_part += part[j] + '_'
                    j += 2
                elif j + 1 < len(part) and part[j].isupper() and part[j+1].isupper() and j + 2 < len(part) and part[j+2].islower():
                    new_part += part[j:j+2] + '_'
                    j += 3
                else:
                    new_part += part[j]
                    j += 1
            snake_case_parts.append(new_part)

    return ''.join(snake_case_parts).lower()
