from typing import List, Tuple

def solve_congruences(congruences: List[Tuple[int, int]]) -> Tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    from math import gcd
    from functools import reduce

    def extended_gcd(a: int, b: int) -> Tuple[int, int, int]:
        if a == 0:
            return (b, 0, 1)
        g, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return (g, x, y)

    def mod_inverse(a: int, m: int) -> int:
        g, x, _ = extended_gcd(a, m)
        if g != 1:
            raise ValueError(f"No modular inverse for {a} modulo {m}")
        return x % m

    def chinese_remainder_theorem(congruences: List[Tuple[int, int]]) -> Tuple[int, int]:
        total = 0
        prod = reduce(lambda x, y: x * y[1], congruences, 1)

        for remainder, modulus in congruences:
            p = prod // modulus
            total += remainder * mod_inverse(p, modulus) * p

        return total % prod, prod

    try:
        return chinese_remainder_theorem(congruences)
    except ValueError:
        return None
