def stabilize_sandpile(grid: List[List[int]]) -> List[List[int]]:
    if not grid or not grid[0]:
        return []

    rows, cols = len(grid), len(grid[0])
    while True:
        new_grid = [[0] * cols for _ in range(rows)]
        changed = False

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] > 3:
                    changed = True
                    new_grid[r][c] = grid[r][c] - 4
                    if r > 0:
                        new_grid[r-1][c] += 1
                    if r < rows - 1:
                        new_grid[r+1][c] += 1
                    if c > 0:
                        new_grid[r][c-1] += 1
                    if c < cols - 1:
                        new_grid[r][c+1] += 1

        if not changed:
            break

        grid = [row[:] for row in new_grid]

    return grid
