def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36 and 2 <= to_base <= 36):
        raise ValueError("Base must be between 2 and 36")

    if number == "":
        return ""

    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    try:
        decimal_number = int(number, from_base)
    except ValueError:
        raise ValueError("Invalid character in number for given base")

    if decimal_number == 0:
        return "0"

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    result = []

    while decimal_number > 0:
        remainder = decimal_number % to_base
        result.append(digits[remainder])
        decimal_number //= to_base

    if is_negative:
        result.insert(0, '-')

    return ''.join(result[::-1])
