def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36 and 2 <= to_base <= 36):
        raise ValueError("Base must be between 2 and 36")

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"

    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    decimal_number = 0
    for char in number:
        if char.lower() not in digits[:from_base]:
            raise ValueError(f"Invalid digit '{char}' for base {from_base}")
        decimal_number = decimal_number * from_base + digits.index(char.lower())

    if decimal_number == 0:
        return '-' if is_negative else '0'

    result = ''
    while decimal_number > 0:
        result = digits[decimal_number % to_base] + result
        decimal_number //= to_base

    return '-' + result if is_negative else result
