def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36 and 2 <= to_base <= 36):
        raise ValueError("Base must be between 2 and 36")

    if number == "":
        return ""
    elif number[0] == "-":
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    # Convert from from_base to decimal
    try:
        decimal_number = int(number, from_base)
    except ValueError:
        raise ValueError("Invalid digit for base {}".format(from_base))

    # Convert from decimal to to_base
    if decimal_number == 0:
        return "0"
    digits = []
    while decimal_number > 0:
        remainder = decimal_number % to_base
        if remainder < 10:
            digits.append(str(remainder))
        else:
            digits.append(chr(remainder - 10 + ord('a')))
        decimal_number //= to_base

    result = ''.join(digits[::-1])
    if is_negative:
        result = "-" + result

    return result
