import yaml

def parse_jobs(text: str) -> list[dict]:
    if not text:
        return []

    jobs = yaml.safe_load(text)
    if not isinstance(jobs, list):
        return []

    parsed_jobs = []
    for job in jobs:
        if not isinstance(job, dict):
            continue

        name = job.get('name', None)
        interval = job.get('interval', None)
        enabled = job.get('enabled', True)

        if name is not None and interval is not None:
            parsed_job = {
                'name': name,
                'interval': interval,
                'enabled': enabled
            }
            parsed_jobs.append(parsed_job)

    return parsed_jobs
