def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    while True:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if result[r][c] >= 4:
                    result[r][c] -= 4
                    changed = True
                    if r > 0:
                        result[r-1][c] += 1
                    if r < rows - 1:
                        result[r+1][c] += 1
                    if c > 0:
                        result[r][c-1] += 1
                    if c < cols - 1:
                        result[r][c+1] += 1

        if not changed:
            break

    return result
