def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(d not in '0123456789abcdefghijklmnopqrstuvwxyz' for d in number):
        raise ValueError("Invalid input")

    is_negative = number.startswith('-')
    if is_negative:
        number = number[1:]

    num = 0
    for char in number:
        if '0' <= char <= '9':
            digit = ord(char) - ord('0')
        else:
            digit = ord(char.lower()) - ord('a') + 10

        if digit >= from_base:
            raise ValueError("Invalid input")

        num = num * from_base + digit

    if num == 0:
        return '0'

    result = ''
    while num > 0:
        digit = num % to_base
        if digit < 10:
            result += chr(ord('0') + digit)
        else:
            result += chr(ord('a') + digit - 10)
        num //= to_base

    if is_negative:
        result += '-'

    return result[::-1]
