from typing import List

def stabilize_sandpile(grid: List[List[int]]) -> List[List[int]]:
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    while True:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if result[r][c] >= 4:
                    result[r][c] -= 4
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            result[nr][nc] += 1
                    changed = True

        if not changed:
            break

    return result
