def subsets_with_sum(nums: List[int], k: int) -> List[List[int]]:
    def backtrack(start: int, current: List[int], remaining: int):
        if remaining == 0:
            result.add(tuple(sorted(current)))
            return
        for i in range(start, len(nums)):
            if nums[i] > remaining:
                break
            backtrack(i + 1, current + [nums[i]], remaining - nums[i])

    result = set()
    backtrack(0, [], k)
    return sorted(list(result))
