def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(d not in '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ' for d in number):
        raise ValueError("Invalid input")

    is_negative = number.startswith('-')
    number = number.lstrip('0').lower()
    if not number:
        return '0'

    decimal_value = 0
    for char in number:
        if '0' <= char <= '9':
            value = ord(char) - ord('0')
        else:
            value = ord(char) - ord('a') + 10
        if value >= from_base:
            raise ValueError("Invalid input")
        decimal_value = decimal_value * from_base + value

    result = ''
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            result += str(remainder)
        else:
            result += chr(ord('a') + remainder - 10)
        decimal_value //= to_base

    if is_negative and result != '0':
        result = '-' + result

    return result[::-1]
