def convert_base(number: str, from_base: int, to_base: int) -> str:
    if number == "":
        raise ValueError("Number cannot be empty")
    if len(number) == 1 and number == "-":
        raise ValueError("Number cannot be just '-'")
    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    if any(d not in digits[:from_base] for d in number):
        raise ValueError(f"Invalid digit for base {from_base}")

    is_negative = number.startswith('-')
    if is_negative:
        number = number[1:]

    num = 0
    power = 0
    for digit in reversed(number):
        num += digits.index(digit.lower()) * (from_base ** power)
        power += 1

    result = ""
    while num > 0:
        result = digits[num % to_base] + result
        num //= to_base

    if result == "":
        result = "0"

    if is_negative:
        result = "-" + result

    return result
