        raise ValueError("Some elements are larger than the bin capacity.")

    bins = []
    sizes.sort(reverse=True)

    for size in sizes:
        placed = False
        for bin_ in bins:
            if sum(bin_) + size <= capacity:
                bin_.append(size)
                placed = True
