def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(c not in '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ' for c in number):
        raise ValueError("Invalid input")

    number = number.lower()
    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    decimal_value = 0
    for char in number:
        if '0' <= char <= '9':
            value = ord(char) - ord('0')
        elif 'a' <= char <= 'z':
            value = ord(char) - ord('a') + 10
        else:
            raise ValueError("Invalid input")

        if value >= from_base:
            raise ValueError("Invalid input")

        decimal_value = decimal_value * from_base + value

    if decimal_value == 0:
        return "0"

    result = ""
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            result = chr(remainder + ord('0')) + result
        else:
            result = chr(remainder - 10 + ord('a')) + result

        decimal_value //= to_base

    if is_negative:
        result = "-" + result

    return result
