import re

def is_local_redirect(target: str, host: str) -> bool:
    if any(char in target for char in r' \t\n\r\x0b\x0c'):
        return False
    if target.startswith('/'):
        return len(target) == 1 or target[1] != '/'
    if re.match(r'https?://', target, re.IGNORECASE):
        url_host = re.search(r'https?://([^/]+)', target, re.IGNORECASE)
        return url_host and url_host.group(1).lower() == host.lower()
    return False
