def min_slides(grid: List[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    start_x, start_y = next((i, j) for i in range(rows) for j in range(cols) if grid[i][j] == 'S')

    queue = [(start_x, start_y, 0)]
    visited = set()

    while queue:
        x, y, steps = queue.pop(0)

        if (x, y) in visited:
            continue
        visited.add((x, y))

        if grid[x][y] == 'E':
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if is_valid(nx, ny) and grid[nx][ny] != '#':
                queue.append((nx, ny, steps + 1))

    return -1
