from typing import List, Tuple

def schedule_jobs(jobs: List[Tuple[str, int, int]]) -> List[str]:
    jobs.sort(key=lambda x: (-x[2], jobs.index(x)))  # Sort by profit in descending order and original index for ties
    slots = [None] * max(job[1] for job in jobs)

    for name, deadline, _ in jobs:
        for slot in range(deadline - 1, -1, -1):
            if slots[slot] is None:
                slots[slot] = name
                break

    return [slot for slot in slots if slot is not None]
