def free_slots(busy: List[Tuple[int, int]], day_start: int, day_end: int, min_len: int) -> List[Tuple[int, int]]:
    if day_start >= day_end:
        return []

    busy = sorted(filter(lambda x: x[0] < x[1], busy))
    merged_busy = [busy[0]]

    for start, end in busy[1:]:
        last_start, last_end = merged_busy[-1]
        if start < last_end:
            merged_busy[-1] = (last_start, max(last_end, end))
        else:
            merged_busy.append((start, end))

    free_gaps = []
    prev_end = day_start

    for start, end in merged_busy:
        if start > prev_end and end - start >= min_len:
            free_gaps.append((prev_end, start))
        prev_end = end

    if day_end > prev_end and day_end - prev_end >= min_len:
        free_gaps.append((prev_end, day_end))

    return free_gaps
