def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]

    def get_ring(ring_index):
        top, bottom = ring_index, n - 1 - ring_index
        left, right = ring_index, n - 1 - ring_index
        ring = []

        while top <= bottom:
            if left == right:
                ring.append(matrix[top][left])
            else:
                for col in range(left, right + 1):
                    ring.append(matrix[top][col])
                for row in range(top + 1, bottom + 1):
                    ring.append(matrix[row][right])
                for col in range(right - 1, left - 1, -1):
                    ring.append(matrix[bottom][col])
                for row in range(bottom - 1, top, -1):
                    ring.append(matrix[row][left])

            top += 1
            bottom -= 1
            left += 1
            right -= 1

        return ring

    def set_ring(ring_index, ring):
        top, bottom = ring_index, n - 1 - ring_index
        left, right = ring_index, n - 1 - ring_index
        index = 0

        while top <= bottom:
            if left == right:
                result[top][left] = ring[index]
            else:
                for col in range(left, right + 1):
                    result[top][col] = ring[index]
                    index += 1
                for row in range(top + 1, bottom + 1):
                    result[row][right] = ring[index]
                    index += 1
                for col in range(right - 1, left - 1, -1):
                    result[bottom][col] = ring[index]
                    index += 1
                for row in range(bottom - 1, top, -1):
                    result[row][left] = ring[index]
                    index += 1

            top += 1
            bottom -= 1
            left += 1
            right -= 1

    for i in range((n + 1) // 2):
        ring = get_ring(i)
        ring_length = len(ring)
        k_normalized = k % ring_length
        if k < 0:
            k_normalized = ring_length - k_normalized
        rotated_ring = ring[k_normalized:] + ring[:k_normalized]
        set_ring(i, rotated_ring)

    return result
