def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]
    num_rings = (n + 1) // 2

    for r in range(num_rings):
        ring_length = 4 * (n - 2 * r) - 4
        effective_k = k % ring_length
        if k < 0:
            effective_k += ring_length

        if effective_k == 0:
            continue

        top, bottom = r, n - r - 1
        left, right = r, n - r - 1

        for _ in range(effective_k):
            temp = result[top][left]

            # Move from top to left
            for i in range(left, right):
                result[top][i] = result[top][i + 1]

            # Move from right to bottom
            for i in range(top, bottom):
                result[i][right] = result[i + 1][right]

            # Move from bottom to right
            for i in range(right, left, -1):
                result[bottom][i] = result[bottom][i - 1]

            # Move from left to top
            for i in range(bottom, top, -1):
                result[i][left] = result[i - 1][left]

            result[top][left + 1] = temp

    return result
