from collections import defaultdict

def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    if not results:
        return []

    teams = set()
    for home, away, _, _ in results:
        teams.add(home)
        teams.add(away)

    team_stats = defaultdict(lambda: {'points': 0, 'goals_for': 0, 'goals_against': 0})

    for home, away, home_goals, away_goals in results:
        team_stats[home]['goals_for'] += home_goals
        team_stats[home]['goals_against'] += away_goals
        team_stats[away]['goals_for'] += away_goals
        team_stats[away]['goals_against'] += home_goals

        if home_goals > away_goals:
            team_stats[home]['points'] += 3
        elif home_goals < away_goals:
            team_stats[away]['points'] += 3
        else:
            team_stats[home]['points'] += 1
            team_stats[away]['points'] += 1

    sorted_teams = sorted(
        [(team, stats['points'], stats['goals_for'] - stats['goals_against'], stats['goals_for'])
         for team, stats in team_stats.items()],
        key=lambda x: (-x[1], -x[2], -x[3], x[0])
    )

    return sorted_teams
