def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(c not in '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ' for c in number):
        raise ValueError("Invalid input")

    is_negative = number.startswith('-')
    if is_negative:
        number = number[1:]

    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    num = sum(digits.index(c.lower()) * (from_base ** i) for i, c in enumerate(reversed(number)))

    if num == 0:
        return '0'

    result = ''
    while num > 0:
        result = digits[num % to_base] + result
        num //= to_base

    return '-' + result if is_negative else result

