from typing import List, Tuple

def schedule_jobs(jobs: List[Tuple[str, int, int]]) -> List[str]:
    jobs.sort(key=lambda x: (-x[2], jobs.index(x)))  # Sort by profit (descending), then by original index
    slots = [None] * max(job[1] for job in jobs)

    for job_name, deadline, _ in jobs:
        for slot_num in range(deadline - 1, -1, -1):
            if slots[slot_num] is None:
                slots[slot_num] = job_name
                break

    return [slot for slot in slots if slot is not None]
