def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [[0] * n for _ in range(n)]

    def get_value(x, y):
        nonlocal n
        while x < 0:
            x += n
        while x >= n:
            x -= n
        while y < 0:
            y += n
        while y >= n:
            y -= n
        return matrix[x][y]

    def set_value(x, y, val):
        nonlocal n
        while x < 0:
            x += n
        while x >= n:
            x -= n
        while y < 0:
            y += n
        while y >= n:
            y -= n
        result[x][y] = val

    for i in range(n // 2):
        ring_length = 4 * (n - 2 * i) - 4
        if ring_length <= 0:
            break
        k %= ring_length

        for j in range(ring_length):
            original_x, original_y = i + (j % (n - 2 * i)) * (1 if j < n - 2 * i else -1), i + (j // (n - 2 * i)) * (1 if j < n - 2 * i else -1)
            new_x, new_y = original_x, original_y
            if k > 0:
                if original_x == i:
                    new_y = original_y + k
                elif original_y == n - 1 - i:
                    new_x = original_x + k
                elif original_x == n - 1 - i:
                    new_y = original_y - k
                else:
                    new_x = original_x - k
            else:
                if original_x == i:
                    new_y = original_y + k
                elif original_y == n - 1 - i:
                    new_x = original_x + k
                elif original_x == n - 1 - i:
                    new_y = original_y - k
                else:
                    new_x = original_x - k

            set_value(new_x, new_y, get_value(original_x, original_y))

    return result
