def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]

    def rotate_layer(layer):
        nonlocal k
        layer_size = 2 * (n - 2 * layer) - 4
        if layer_size <= 0:
            return

        k %= layer_size
        if k == 0:
            return

        top = layer
        bottom = n - layer - 1
        left = layer
        right = n - layer - 1

        temp = [result[top][i] for i in range(left, right + 1)]

        # Rotate to the right
        if k > 0:
            for i in range(left, right + 1):
                result[top][i] = result[bottom - (i - left)][left]

            for i in range(top, bottom):
                result[i][left] = result[bottom][left + (i - top)]

            for i in range(right, left, -1):
                result[bottom][i] = result[top + (right - i)][right]

            for i in range(bottom, top, -1):
                result[i][right] = temp.pop(0)

        # Rotate to the left
        else:
            k = -k
            for i in range(right, left, -1):
                result[top][i] = result[bottom - (i - left)][left]

            for i in range(bottom, top, -1):
                result[i][left] = result[bottom][left + (i - top)]

            for i in range(left, right + 1):
                result[bottom][i] = result[top + (right - i)][right]

            for i in range(top, bottom):
                result[i][right] = temp.pop()

    for layer in range((n + 1) // 2):
        rotate_layer(layer)

    return result
