def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]
    k = k % n

    def rotate_layer(layer):
        if layer == 0:
            return
        temp = result[layer][layer:-layer]
        for i in range(len(temp)):
            result[layer][layer + i] = result[layer + i][-layer - 1]
            result[layer + i][-layer - 1] = result[-layer - 1][-layer - 1 - i]
            result[-layer - 1][-layer - 1 - i] = result[-layer - 1 - i][layer]
            result[-layer - 1 - i][layer] = temp[i]

    for layer in range((n + 1) // 2):
        rotate_layer(layer)

    return result
