def parse_csv(text: str) -> list[list[str]]:
    records = []
    lines = text.strip().split('\n')

    for line in lines:
        if not line:
            records.append([])
            continue

        fields = []
        i = 0
        while i < len(line):
            if line[i] == '"':
                start = i
                i += 1
                while i < len(line) and (line[i] != '"' or line[i-1] == '\\'):
                    i += 1
                if i >= len(line):
                    raise ValueError("Unmatched quote")
                fields.append(line[start+1:i].replace('""', '"'))
                i += 1
            else:
                end = i + 1
                while end < len(line) and line[end] != ',':
                    end += 1
                fields.append(line[i:end])
                i = end + 1
        records.append(fields)

    return records
