from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def can_move(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    def slide(x, y, dx, dy):
        while can_move(x + dx, y + dy):
            x += dx
            y += dy
        return x, y

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        (x, y), steps = queue.popleft()
        if (x, y) == end:
            return steps
        for dx, dy in directions:
            nx, ny = slide(x, y, dx, dy)
            if (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(((nx, ny), steps + 1))

    return -1
