def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    num_columns = len(rows[0])
    if any(len(row) != num_columns for row in rows):
        raise ValueError("All rows must have the same number of columns")

    col_widths = [max(len(cell) for cell in column) for column in zip(*rows)]

    def pad_cell(cell: str, width: int, align: str) -> str:
        if align == "l":
            return cell.ljust(width)
        elif align == "r":
            return cell.rjust(width)
        elif align == "c":
            return cell.center(width)
        else:
            raise ValueError(f"Invalid alignment character: {align}")

    formatted_rows = []
    for row, align in zip(rows, aligns):
        formatted_cells = [pad_cell(cell, width, align) for cell, width in zip(row, col_widths)]
        formatted_rows.append(" | ".join(formatted_cells))

    return "\n".join(formatted_rows)
