import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    pattern = re.compile(r'\s*(?:(\d+\.\d+|\d+)|([a-zA-Z_]\w*)|([+\-*/<>=(),])|((?<!\.)\.))')
    for match in pattern.finditer(source):
        kind, text = match.groups()
        if kind:
            if kind.isdigit():
                kind = 'NUMBER'
            elif kind.isalpha() or kind[0] == '_':
                kind = 'NAME'
            else:
                kind = 'OP'
            tokens.append((kind, text))
        else:
            raise ValueError(f"Invalid character found: {match.group(0)}")
    return tokens
