from collections import defaultdict

def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    if not results:
        return []

    table = defaultdict(lambda: [0, 0, 0])

    for home, away, home_goals, away_goals in results:
        table[home][0] += 3 if home_goals > away_goals else 1 if home_goals == away_goals else 0
        table[home][1] += home_goals - away_goals
        table[home][2] += home_goals
        table[away][0] += 3 if away_goals > home_goals else 1 if away_goals == home_goals else 0
        table[away][1] += away_goals - home_goals
        table[away][2] += away_goals

    return sorted(table.items(), key=lambda x: (-x[1][0], -x[1][1], -x[1][2], x[0]))

