import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with http or https
    if not url.startswith(('http://', 'https://')):
        return False

    # Remove query parameters and fragment identifier
    url = re.split(r'[?#]', url)[0]

    # Extract host part
    host_part = url.split('/')[2] if '/' in url else url

    # Check for invalid characters
    if any(c in host_part for c in r' \t\n\r\x0b\x0c'):
        return False

    # Split host by dots and check each label
    labels = host_part.split('.')
    if len(labels[-1]) == 0 or labels[-1].isdigit():
        return False

    for label in labels[:-1]:
        if not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False

    # Check if it's localhost or ends with .localhost
    if host_part.lower() in ('localhost', '.localhost'):
        return False

    # Check port number
    if ':' in host_part:
        _, port = host_part.rsplit(':', 1)
        if not (port.isdigit() and int(port) == 443):
            return False

    return True
