import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with http or https
    if not url.startswith(('http://', 'https://')):
        return False

    # Remove query parameters and fragment identifier
    url = re.split(r'[?#]', url)[0]

    # Check for invalid characters
    if re.search(r'[\x00-\x1F\x7F]|//|\\|\s', url):
        return False

    # Extract host part
    host_part = url.split('//')[1].split('/')[0]

    # Check for localhost or .localhost in host part
    if host_part == 'localhost' or host_part.endswith('.localhost'):
        return False

    # Split host by dots and validate each label
    labels = host_part.split('.')
    for label in labels[:-1]:
        if not label or not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False
    if not re.match(r'^[a-zA-Z]+$', labels[-1]):
        return False

    # Check port number
    port_index = host_part.find(':')
    if port_index != -1:
        port = int(host_part[port_index + 1:])
        if port != 443:
            return False

    return True

