import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https:// (case-insensitive)
    if not url.lower().startswith('https://'):
        return False

    # Remove query parameters and fragment identifier
    url = re.split(r'[?#]', url)[0]

    # Check for forbidden characters
    if any(ord(c) < 32 or ord(c) == 127 for c in url):
        return False

    # Split URL into components
    parts = url[len('https://'):].split('/')
    if len(parts) > 1:
        parts = parts[0].split('@')[-1].split(':')
    else:
        parts = [parts[0]]

    host = parts[0]
    if host.endswith('.'):
        host = host[:-1]

    # Check if host is localhost
    if host.lower() in ['localhost', 'localhost.']:
        return False

    # Check if host ends with .localhost
    if host.lower().endswith('.localhost'):
        return False

    # Split host into labels
    labels = host.split('.')

    # Check number of labels and last label
    if len(labels) < 2 or not labels[-1].isalpha():
        return False

    # Check each label
    for label in labels:
        if not label or not re.match(r'^[a-z0-9-]+$', label):
            return False

    # Check port if present
    if len(parts) > 1 and parts[1] != '443':
        return False

    return True
