import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with http or https
    if not url.startswith(('http://', 'https://')):
        return False

    # Remove any query parameters and fragment identifiers
    url = re.split(r'[?#]', url)[0]

    # Extract the host part of the URL
    host_part = url.split('//')[1].split('/')[0]

    # Check for invalid characters in the host part
    if re.search(r'[\x00-\x2F\x3A-\x40\x5B-\x60\x7B-\x7F]', host_part):
        return False

    # Split the host into labels
    labels = host_part.split('.')

    # Check the number of labels and their validity
    if len(labels) < 2 or labels[-1] == '':
        return False

    for label in labels[:-1]:
        if not label or not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False

    if not re.match(r'^[a-zA-Z]+$', labels[-1]):
        return False

    # Check if the port is present and valid
    if ':' in host_part:
        port = host_part.split(':')[1]
        if not port.isdigit() or int(port) != 443:
            return False

    # Check if the host is localhost or ends with .localhost
    if host_part.lower() in ('localhost', '.localhost'):
        return False

    return True
