import re
from urllib.parse import urlparse

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with http or https
    if not url.startswith(('http://', 'https://')):
        return False

    # Remove any query parameters and fragment identifiers
    parsed_url = urlparse(url)
    url = parsed_url.scheme + '://' + parsed_url.netloc + parsed_url.path

    # Check for disallowed characters in the URL
    if re.search(r'[\\ / \x00-\x1F\x7F]', url):
        return False

    # Split the host by dots and validate each label
    labels = url.split('.')
    if len(labels[-1]) == 0 or labels[-1].isdigit():
        return False

    for label in labels[:-2]:
        if not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False

    if not re.match(r'^[a-zA-Z]+$', labels[-2]):
        return False

    # Check if the port is present and valid
    if parsed_url.port is not None and parsed_url.port != 443:
        return False

    # Check if the hostname is localhost or ends with .localhost
    if parsed_url.hostname in ('localhost', f'{parsed_url.hostname}.localhost'):
        return False

    # Check if the hostname can be resolved to an IP address
    try:
        socket.gethostbyname(parsed_url.hostname)
    except socket.gaierror:
        return False

    return True
