import ast

class FilterExpressionEvaluator(ast.NodeVisitor):
    def __init__(self, record):
        self.record = record

    def visit_Name(self, node):
        if node.id in self.record:
            return self.record[node.id]
        else:
            raise ValueError(f"Unknown variable: {node.id}")

    def visit_Num(self, node):
        return node.n

    def visit_Str(self, node):
        return node.s

    def visit_Compare(self, node):
        left = self.visit(node.left)
        ops = {
            ast.Lt: lambda x, y: x < y,
            ast.LtE: lambda x, y: x <= y,
            ast.Gt: lambda x, y: x > y,
            ast.GtE: lambda x, y: x >= y,
            ast.Eq: lambda x, y: x == y,
            ast.NotEq: lambda x, y: x != y,
        }
        right = self.visit(node.comparators[0])
        return ops[type(node.ops[0])](left, right)

    def visit_BinOp(self, node):
        left = self.visit(node.left)
        right = self.visit(node.right)
        ops = {
            ast.Add: lambda x, y: x + y,
            ast.Sub: lambda x, y: x - y,
            ast.Mult: lambda x, y: x * y,
            ast.Div: lambda x, y: x / y,
            ast.Mod: lambda x, y: x % y,
            ast.Pow: lambda x, y: x ** y,
        }
        return ops[type(node.op)](left, right)

    def visit_UnaryOp(self, node):
        operand = self.visit(node.operand)
        ops = {
            ast.USub: lambda x: -x,
            ast.Not: lambda x: not x,
        }
        return ops[type(node.op)](operand)

    def visit_BoolOp(self, node):
        values = [self.visit(value) for value in node.values]
        ops = {
            ast.And: all,
            ast.Or: any,
        }
        return ops[type(node.op)](values)

def matches_filter(expression: str, record: dict) -> bool:
    try:
        parsed_expression = ast.parse(expression, mode='eval').body
        evaluator = FilterExpressionEvaluator(record)
        return evaluator.visit(parsed_expression)
    except (SyntaxError, AttributeError, ValueError) as e:
        raise ValueError("Invalid expression") from e
