from collections import OrderedDict

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return ([], [])

    cache = OrderedDict()
    results = []

    for op in operations:
        if op[0] == "put":
            if op[1] in cache:
                cache.move_to_end(op[1])
            cache[op[1]] = op[2]
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif op[0] == "get":
            if op[1] in cache:
                cache.move_to_end(op[1])
                results.append(cache[op[1]])
            else:
                results.append(None)

    keys = list(cache.keys())

    return (results, keys)
