import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with http or https
    if not url.startswith(('http://', 'https://')):
        return False

    # Remove protocol part for further checks
    url = url[len('http://'):] if url.startswith('http://') else url[len('https://'):]

    # Check for backslash, space, and control characters
    if any(char in url for char in r'\x00-\x1F\x7F'):
        return False

    # Split host by '@' to handle user:password part
    parts = url.split('@')
    host_part = parts[-1].split(':')[0] if ':' in parts[-1] else parts[-1]

    # Check if host ends with '.'
    if host_part.endswith('.'):
        host_part = host_part[:-1]

    # Split host by '.' and validate each label
    labels = host_part.split('.')
    if len(labels) < 2 or labels[-1] == '':
        return False

    for label in labels:
        if not all(c.isalnum() or c == '-' for c in label):
            return False
        if label[0] == '-' or label[-1] == '-':
            return False

    # Check if host is localhost or ends with .localhost
    if host_part.lower() in ('localhost', '') or host_part.lower().endswith('.localhost'):
        return False

    # Check if port is present and not equal to 443
    if ':' in parts[-1]:
        port = int(parts[-1].split(':')[-1])
        if port != 443:
            return False

    return True
