def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    num_cols = len(rows[0])
    col_widths = [max(len(cell) for cell in column) for column in zip(*rows)]

    def format_cell(cell: str, width: int, align: str) -> str:
        padding = width - len(cell)
        if align == "l":
            return cell + " " * padding
        elif align == "r":
            return " " * padding + cell
        elif align == "c":
            left_padding = padding // 2
            right_padding = padding - left_padding
            return " " * left_padding + cell + " " * right_padding

    formatted_rows = []
    for row in rows:
        formatted_cells = [
            format_cell(row[i], col_widths[i], aligns[i]) for i in range(num_cols)
        ]
        formatted_rows.append(" | ".join(formatted_cells))

    return "\n".join(formatted_rows)
