import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https://
    if not url.lower().startswith('https://'):
        return False

    # Remove any query parameters or fragment identifiers
    url = re.split(r'[?#]', url)[0]

    # Check for backslashes, spaces, or control characters
    if '\\' in url or ' ' in url or any(ord(c) < 32 or ord(c) == 127 for c in url):
        return False

    # Extract the host part of the URL
    parts = url[len('https://'):].split('/')
    if '@' in parts[0]:
        parts[0] = parts[0].split('@')[1]
    host = parts[0].rstrip('.')

    # Check if the host is localhost or ends with .localhost
    if host.lower() == 'localhost' or host.endswith('.localhost', -len('.localhost')):
        return False

    # Split the host into labels and check their format
    labels = host.split('.')
    if len(labels) < 2:
        return False
    for label in labels[:-1]:
        if not label or not all(c.isalnum() or c == '-' for c in label):
            return False
    last_label = labels[-1]
    if not last_label or not last_label.isalpha():
        return False

    # Check if the port is present and is 443
    if ':' in host:
        port = host.split(':')[1]
        if port != '443':
            return False

    return True
