def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program):
        if len(stack) > 1000:
            raise RuntimeError("Stack overflow")

        instruction = program[ip].split()
        op = instruction[0]

        if op == "PUSH":
            value = int(instruction[1])
            stack.append(value)
        elif op == "POP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif op == "DUP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif op == "SWAP":
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for SWAP")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == "ADD":
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for ADD")
            stack.append(stack.pop() + stack.pop())
        elif op == "SUB":
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for SUB")
            stack.append(-stack.pop() + stack.pop())
        elif op == "MUL":
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for MUL")
            stack.append(stack.pop() * stack.pop())
        elif op == "JMP":
            target = int(instruction[1])
            if target < 0 or target >= len(program):
                raise ValueError("Invalid jump target")
            ip = target - 1
        elif op == "JZ":
            if len(stack) < 1:
                raise ValueError("Not enough elements on stack for JZ")
            if stack[-1] == 0:
                target = int(instruction[1])
                if target < 0 or target >= len(program):
                    raise ValueError("Invalid jump target")
                ip = target - 1
        elif op == "HALT":
            break
        else:
            raise ValueError(f"Unknown operation: {op}")

        ip += 1

    return stack
