def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program) and len(stack) <= 2:
        instruction = program[ip].split()
        if instruction[0] == 'PUSH':
            stack.append(int(instruction[1]))
        elif instruction[0] == 'POP':
            if stack:
                stack.pop()
        elif instruction[0] == 'DUP':
            if stack:
                stack.append(stack[-1])
        elif instruction[0] == 'SWAP':
            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction[0] == 'ADD':
            if len(stack) >= 2:
                stack.append(stack.pop() + stack.pop())
        elif instruction[0] == 'SUB':
            if len(stack) >= 2:
                stack.append(-stack.pop() + stack.pop())
        elif instruction[0] == 'MUL':
            if len(stack) >= 2:
                stack.append(stack.pop() * stack.pop())
        elif instruction[0] == 'JMP':
            ip = int(instruction[1]) - 1
        elif instruction[0] == 'JZ':
            if not stack or not stack.pop():
                ip = int(instruction[1]) - 1

        ip += 1
        if ip >= len(program):
            return stack[::-1]

        if len(stack) > 2:
            return None

        if max_instructions <= 0:
            return None

        max_instructions -= 1

    return None
