import ipaddress

def is_public_ip(ip_str: str) -> bool:
    try:
        # Normalize and validate the IP address
        ip = ipaddress.ip_address(ip_str)

        # Check if it's a private IP
        if ip.is_private:
            return False

        # Check for IPv4 mapped to IPv6
        if isinstance(ip, ipaddress.IPv6Address):
            ipv4_part = ip.ipv4_mapped
            if ipv4_part and ipv4_part.is_private:
                return False

        # Check for multicast addresses
        if ip.is_multicast:
            return False

        # Check for loopback addresses
        if ip.is_loopback:
            return False

        # Check for link-local addresses
        if ip.is_link_local:
            return False

        # Check for unspecified address
        if ip.is_unspecified:
            return False

        # Check for reserved addresses
        if ip.is_reserved:
            return False

        # Check for documentation addresses
        if ip.is_documentation:
            return False

        # Check for shared address space
        if ip.is_site_local:
            return False

        # If none of the above conditions are met, it's a public IP
        return True

    except ValueError:
        # If there was an error parsing the IP address, it's not valid
        return False
