def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_instructions = 1000
    instruction_count = 0

    while ip < len(program):
        if instruction_count >= max_instructions:
            raise RuntimeError("Too many instructions executed")

        instruction = program[ip]
        parts = instruction.split()
        opcode = parts[0]

        if opcode == "PUSH":
            value = int(parts[1])
            stack.append(value)
        elif opcode == "POP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif opcode == "DUP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif opcode == "SWAP":
            if len(stack) < 2:
                raise ValueError("Not enough values on stack for SWAP")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == "ADD":
            if len(stack) < 2:
                raise ValueError("Not enough values on stack for ADD")
            stack.append(stack.pop() + stack.pop())
        elif opcode == "SUB":
            if len(stack) < 2:
                raise ValueError("Not enough values on stack for SUB")
            stack.append(-stack.pop() + stack.pop())
        elif opcode == "MUL":
            if len(stack) < 2:
                raise ValueError("Not enough values on stack for MUL")
            stack.append(stack.pop() * stack.pop())
        elif opcode == "JMP":
            target = int(parts[1])
            if target < 0 or target >= len(program):
                raise ValueError("Invalid JMP target")
            ip = target
            continue
        elif opcode == "JZ":
            if len(stack) < 1:
                raise ValueError("Not enough values on stack for JZ")
            if stack[-1] == 0:
                target = int(parts[1])
                if target < 0 or target >= len(program):
                    raise ValueError("Invalid JZ target")
                ip = target
                continue
            else:
                stack.pop()
        elif opcode == "HALT":
            break

        ip += 1
        instruction_count += 1

    return stack
