    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program):
        if max_instructions <= 0:
            raise RuntimeError("Too many instructions executed")

        instruction = program[ip].split()
        op = instruction[0]

        if op == "PUSH":
            n = int(instruction[1])
            stack.append(n)
        elif op == "POP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif op == "DUP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif op == "SWAP":
            if len(stack) < 2:
                raise ValueError("Not enough values on stack for SWAP")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == "ADD":
            if len(stack) < 2:
                raise ValueError("Not enough values on stack for ADD")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif op == "SUB":
            if len(stack) < 2:
                raise ValueError("Not enough values on stack for SUB")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif op == "MUL":
            if len(stack) < 2:
                raise ValueError("Not enough values on stack for MUL")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif op == "JMP":
            t = int(instruction[1])
            if t >= len(program):
                raise ValueError("Jump target out of range")
