    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program) and len(stack) <= 1000:
        instruction = program[ip]
        parts = instruction.split()

        if parts[0] == 'PUSH':
            stack.append(int(parts[1]))
        elif parts[0] == 'POP':
            if stack:
                stack.pop()
        elif parts[0] == 'DUP':
            if stack:
                stack.append(stack[-1])
        elif parts[0] == 'SWAP':
            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
        elif parts[0] == 'ADD':
            if len(stack) >= 2:
                stack.append(stack.pop() + stack.pop())
        elif parts[0] == 'SUB':
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
        elif parts[0] == 'MUL':
            if len(stack) >= 2:
                stack.append(stack.pop() * stack.pop())
        elif parts[0] == 'JMP':
            try:
                ip = int(parts[1])
            except ValueError:
                return None
        elif parts[0] == 'JZ':
            if len(stack) >= 1:
                if stack.pop() == 0:
                    try:
