            account, amount = args
            if account not in final_balances or amount <= 0:
                failed.append(i)
                continue
            final_balances[account] += amount

        elif action == 'withdraw':
            account, amount = args
            if account not in final_balances or amount <= 0 or final_balances[account] < amount:
                failed.append(i)
                continue
            final_balances[account] -= amount

        elif action == 'transfer':
            src, dest, amount = args
            fee = 2
            if src not in final_balances or dest not in final_balances or amount <= 0 or final_balances[src] < amount + fee:
                failed.append(i)
                continue
            final_balances[src] -= (amount + fee)
            final_balances[dest] += amount

        elif action == 'freeze':
            account, = args
            if account not in final_balances:
                failed.append(i)
                continue

        elif action == 'unfreeze':
            account, = args
            if account not in final_balances:
                failed.append(i)
                continue

        else:
            failed.append(i)

    return final_balances, failed[::-1]
