def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program) and len(stack) <= 1000:
        instruction = program[ip]
        parts = instruction.split()
        if parts[0] == 'PUSH':
            stack.append(int(parts[1]))
        elif parts[0] == 'POP':
            if not stack:
                raise ValueError("POP from empty stack")
            stack.pop()
        elif parts[0] == 'DUP':
            if not stack:
                raise ValueError("DUP on empty stack")
            stack.append(stack[-1])
        elif parts[0] == 'SWAP':
            if len(stack) < 2:
                raise ValueError("SWAP with less than two elements on stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif parts[0] == 'ADD':
            if len(stack) < 2:
                raise ValueError("ADD with less than two elements on stack")
            stack.append(stack.pop() + stack.pop())
        elif parts[0] == 'SUB':
            if len(stack) < 2:
                raise ValueError("SUB with less than two elements on stack")
            stack.append(-stack.pop() + stack.pop())
        elif parts[0] == 'MUL':
            if len(stack) < 2:
                raise ValueError("MUL with less than two elements on stack")
            stack.append(stack.pop() * stack.pop())
        elif parts[0] == 'JMP':
            try:
                target = int(parts[1])
                if target < 0 or target >= len(program):
                    raise ValueError(f"Invalid JMP target {target}")
                ip = target
                continue
            except ValueError:
                raise ValueError(f"Invalid JMP target {parts[1]}")
        elif parts[0] == 'JZ':
            if len(stack) < 1:
                raise ValueError("JZ with empty stack")
            value = stack.pop()
            if value == 0:
                try:
                    target = int(parts[1])
                    if target < 0 or target >= len(program):
                        raise ValueError(f"Invalid JZ target {target}")
                    ip = target
                    continue
                except ValueError:
                    raise ValueError(f"Invalid JZ target {parts[1]}")
        elif parts[0] == 'HALT':
            break
        else:
            raise ValueError(f"Unknown instruction {instruction}")

        ip += 1

    if len(stack) > 1000:
        raise RuntimeError("Stack overflow")

    return stack[::-1]
