from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def bfs_with_one_break():
        queue = deque([(0, 0, False)])
        visited = set()

        while queue:
            x, y, broken = queue.popleft()

            if (x, y, broken) in visited:
                continue

            visited.add((x, y, broken))

            if x == rows - 1 and y == cols - 1:
                return grid[x][y]

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if 0 <= nx < rows and 0 <= ny < cols:
                    if grid[nx][ny] == '0':
                        queue.append((nx, ny, broken))
                    elif not broken:
                        queue.append((nx, ny, True))

        return -1

    return bfs_with_one_break()
