def shortest_path_one_break(grid: List[List[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs_with_break(start_row, start_col):
        queue = [(start_row, start_col, False)]
        visited = set()
        while queue:
            row, col, broke = queue.pop(0)
            if (row, col, broke) in visited:
                continue
            visited.add((row, col, broke))
            if row == rows - 1 and col == cols - 1:
