            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < rows and 0 <= new_col < cols:
                    if grid[new_row][new_col] == 0 or broke:
                        queue.append((new_row, new_col, broke or grid[new_row][new_col] == 1))
        return False

    return 1 if bfs_with_break(0, 0) else 2
