from collections import defaultdict

def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n
    bridges = []

    def dfs(u):
        nonlocal time
        visited[u] = True
        disc[u] = low[u] = time
        time += 1

        for v in graph[u]:
            if not visited[v]:
                parent[v] = u
                dfs(v)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((u, v) if u < v else (v, u))
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

    time = 0
    for i in range(n):
        if not visited[i]:
            dfs(i)

    return bridges

