    # Get dimensions of matrices
    m = len(a)
    k = len(b)
    n = len(b[0])

    # Initialize the result matrix with zeros
    result = [[0 for _ in range(n)] for _ in range(m)]

    # Perform matrix multiplication
    for i in range(m):
        for j in range(n):
            for l in range(k):
                result[i][j] += a[i][l] * b[l][j]

    return result

