from typing import List

def weighted_harmonic_mean(vals: List[float], weights: List[float]) -> float:
    if not vals or len(vals) != len(weights) or sum(weights) == 0:
        return 0.0

    total_weight = sum(w for v, w in zip(vals, weights) if v > 0)
    if total_weight == 0:
        return 0.0

    weighted_sum = sum(w / v for v, w in zip(vals, weights) if v > 0)

    return round(len(vals) / weighted_sum, 3)
