from typing import List

def smallest_lcs(a: str, b: str) -> str:
    m, n = len(a), len(b)
    dp = [[['' for _ in range(n + 1)] for _ in range(m + 1)] for _ in range(2)]

    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if a[i] == b[j]:
                dp[0][i][j] = a[i] + dp[1][i + 1][j + 1]
            else:
                dp[0][i][j] = max(dp[1][i + 1][j], dp[1][i][j + 1])
            dp[1][i][j] = dp[0][i][j]

    lcs = dp[0][0][0]
    result = []

    def backtrack(i: int, j: int, current: str) -> None:
        nonlocal lcs, result
        if i == m or j == n:
            if len(current) > len(lcs) or (len(current) == len(lcs) and current < lcs):
                lcs = current
                result = [current]
            elif len(current) == len(lcs):
                result.append(current)
            return
        if a[i] == b[j]:
            backtrack(i + 1, j + 1, current + a[i])
        backtrack(i + 1, j, current)
        backtrack(i, j + 1, current)

    backtrack(0, 0, '')
    return min(result) if result else ''
