        if row == n:
            return 1
        count = 0
        for col in range(n):
            if (row, col) not in blocked and is_valid(board, row, col):
                board[row][col] = 1
                count += backtrack(row + 1)
                board[row][col] = 0
        return count

    if n == 0:
        return 1
    board = [[0] * n for _ in range(n)]
    return backtrack()
