def matrix_multiply_mod(a: List[List[int]], b: List[List[int]], mod: int) -> List[List[int]]:
    n = len(a)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
    return result

def matrix_power_mod(matrix: List[List[int]], exp: int, mod: int) -> List[List[int]]:
    n = len(matrix)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1

    while exp > 0:
        if exp % 2 == 1:
            result = matrix_multiply_mod(result, matrix, mod)
        matrix = matrix_multiply_mod(matrix, matrix, mod)
        exp //= 2

    return result
