def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []

    for kind, item, quantity in events:
        if kind == 'receive':
            if item not in stock:
                stock[item] = 0
            stock[item] += quantity

            # Process waiting orders for this item
            while waiting and waiting[0][0] == item:
                _, wait_quantity = waiting.pop(0)
                if wait_quantity <= stock[item]:
                    stock[item] -= wait_quantity
                else:
                    waiting.insert(0, (item, wait_quantity - stock[item]))
                    break

    return stock, waiting
