from typing import List

def stabilize_sandpile(grid: List[List[int]]) -> List[List[int]]:
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def collapse(r: int, c: int):
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                grid[nr][nc] += 1

    while True:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] >= 4:
                    grid[r][c] -= 4
                    collapse(r, c)
                    changed = True
        if not changed:
            break

    return grid
