    if not number or number == '-' or any(c.lower() not in '0123456789abcdefghijklmnopqrstuvwxyz'[:from_base] for c in number):
        raise ValueError("Invalid input")

    is_negative = number.startswith('-')
    if is_negative:
        number = number[1:]

    num = 0
    for char in number:
        num *= from_base
        if '0' <= char <= '9':
            num += ord(char) - ord('0')
        else:
            num += ord(char.lower()) - ord('a') + 10

    if num == 0:
        return "0"

    result = ""
    while num > 0:
        remainder = num % to_base
        if remainder < 10:
            result = chr(remainder + ord('0')) + result
        else:
            result = chr(remainder - 10 + ord('a')) + result
        num //= to_base

    if is_negative:
        result = "-" + result

    return result
