import heapq

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return (0, [start])

    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))

    pq = [(0, start, [])]
    visited = set()

    while pq:
        current_cost, current_node, path = heapq.heappop(pq)

        if current_node in visited:
            continue

        visited.add(current_node)
        path = path + [current_node]

        if current_node == goal:
            return (current_cost, path)

        for neighbor, weight in graph[current_node]:
            if neighbor not in visited:
                heapq.heappush(pq, (current_cost + weight, neighbor, path))

    return None
