import re

def parse_csv(text: str) -> list[list[str]]:
    def parse_quoted_field(match):
        return match.group(1).replace('""', '"')

    def parse_unquoted_field(field):
        return field.strip()

    lines = text.split('\n')
    result = []

    for line in lines:
        if line.startswith('"'):
            fields = re.findall(r'"([^"]*(?:""[^"]*)*)"|([^",\n]+)', line)
            parsed_fields = [parse_quoted_field(m) if m else parse_unquoted_field(f) for m, f in fields]
        else:
            parsed_fields = [field.strip() for field in line.split(',')]

        result.append(parsed_fields)

    return result
