def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    blocked_set = set(blocked)

    def is_valid(board, row, col):
        for i in range(n):
            if board[i][col] == 'Q' or board[row][i] == 'Q':
                return False
            if 0 <= row + i < n and 0 <= col + i < n and board[row + i][col + i] == 'Q':
                return False
            if 0 <= row - i < n and 0 <= col - i < n and board[row - i][col - i] == 'Q':
                return False
        return True

    def backtrack(row=0, count=0):
        if row == n:
            return 1
        for col in range(n):
            if (row, col) in blocked_set or board[row][col] != '.':
                continue
            if is_valid(board, row, col):
                board[row][col] = 'Q'
                count += backtrack(row + 1)
                board[row][col] = '.'
        return count

    board = [['.' for _ in range(n)] for _ in range(n)]
    return backtrack()
