import re

def parse_csv(text: str) -> list[list[str]]:
    def parse_quoted_field(field):
        return re.sub(r'""', '"', field[1:-1])

    def parse_unquoted_field(field):
        return field

    result = []
    lines = text.split('\n')
    for line in lines:
        if line.strip():
            fields = re.split(r'(,\"|(?<!")\n)', line)
            parsed_fields = []
            i = 0
            while i < len(fields):
                if fields[i].startswith('"'):
                    j = i + 1
                    while j < len(fields) and not fields[j].endswith('"'):
                        j += 1
                    if j == len(fields):
                        raise ValueError("Unmatched opening quote")
                    parsed_fields.append(parse_quoted_field(''.join(fields[i:j+1])))
                    i = j + 1
                else:
                    parsed_fields.append(parse_unquoted_field(fields[i]))
                    i += 1
            result.append(parsed_fields)
    return result
