import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https:// (case-insensitive)
    if not url.lower().startswith('https://'):
        return False

    # Remove query parameters and fragment identifier
    url = re.split(r'[?#]', url)[0]

    # Check for disallowed characters
    if re.search(r'[\x00-\x1F\x7F\\ ]', url):
        return False

    # Split URL into components
    parts = url[len('https://'):].split('/')
    if len(parts) < 2:
        return False

    host, *path = parts
    if host.endswith('.'):
        host = host[:-1]

    # Validate host format
    if '.' not in host or host.count('.') < 2:
        return False

    labels = host.split('.')
    if not all(re.match(r'^[a-zA-Z0-9-]+$', label) for label in labels[:-1]):
        return False
    if not re.match(r'^[a-zA-Z]+$', labels[-1]):
        return False

    # Check for localhost variations
    if re.match(r'^(localhost|127\.0\.0\.1|::1)$', host, re.IGNORECASE):
        return False

    # Check for port
    if ':' in host:
        _, port = host.split(':')
        if port != '443':
            return False

    return True
