import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    source = ''.join(filter(lambda x: x.isprintable(), source))
    if not source.strip():
        return []

    tokens = []
    i = 0
    while i < len(source):
        match = None

        # Try to match NUMBER
        if source[i].isdigit() or (source[i] == '.' and i + 1 < len(source) and source[i + 1].isdigit()):
            match = re.match(r'\d+(\.\d+)?', source[i:])

        # Try to match NAME
        if not match and (source[i].isalpha() or source[i] == '_'):
            match = re.match(r'[a-zA-Z_]\w*', source[i:])

        # Try to match OP
        if not match:
            for op in ['==', '!=', '<=', '>=', '+', '-', '*', '/', '<', '>', '=', '(', ')', ',']:
                if source.startswith(op, i):
                    match = re.match(re.escape(op), source[i:])
                    break

        if not match:
            raise ValueError(f"Invalid character at position {i}: {source[i]}")

        kind, text = match.groups()
        tokens.append((kind, text))
        i += match.end()

    return tokens
