import re

def evaluate_expression(expr: str) -> int:
    # Remove spaces
    expr = expr.replace(" ", "")

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(int(left / right))
        elif operator == '^':
            values.append(int(pow(left, right)))

    def greater_precedence(op1, op2):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
        return precedence[op1] > precedence[op2]

    operators = []
    values = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit() or (expr[i] == '-' and (i == 0 or expr[i-1] in '(*+-/^')):
            j = i
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '-'):
                j += 1
            values.append(int(expr[i:j]))
            i = j
        elif expr[i] in '+-*/^(':
            while (operators and operators[-1] != '(' and
                   greater_precedence(operators[-1], expr[i])):
                apply_operator(operators, values)
            operators.append(expr[i])
            i += 1
        elif expr[i] == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
            i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

# Example usage:
result = evaluate_expression("2^3^2")
print(result)  # Output: 512
