def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    for size in sizes:
        if size > capacity:
            raise ValueError("Item size exceeds bin capacity")

    sizes.sort(reverse=True)
    bins = []

    for size in sizes:
        placed = False
        for bin_ in bins:
            if sum(bin_) + size <= capacity:
                bin_.append(size)
                placed = True
                break
        if not placed:
            bins.append([size])

    return bins
