from collections import defaultdict

def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    if not results:
        return []

    standings = defaultdict(lambda: [0, 0, 0])

    for home, away, home_goals, away_goals in results:
        standings[home][0] += 1
        standings[away][0] += 1
        if home_goals > away_goals:
            standings[home][1] += 3
            standings[away][2] += 1
        elif home_goals < away_goals:
            standings[away][1] += 3
            standings[home][2] += 1
        else:
            standings[home][1] += 1
            standings[away][1] += 1

        standings[home][2] += home_goals
        standings[away][2] += away_goals

    return sorted([(team, *standings[team]) for team in standings], 
                  key=lambda x: (-x[1], -x[2], -x[3], x[0]))
