import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    pattern = r'\s*(?:(\d+\.\d+|\d+)|([a-zA-Z_]\w*)|(["\'](?:\\.|[^"\\\n])*["\']|[+\-*/<>=(),])|\.)'
    matches = re.finditer(pattern, source)

    for match in matches:
        kind, text = None, match.group(0).strip()
        if text.isdigit() or (text.count('.') == 1 and text.replace('.', '', 1).isdigit()):
            kind = "NUMBER"
        elif re.match(r'^[a-zA-Z_]\w*$', text):
            kind = "NAME"
        elif text in "+-*/<>=(),":
            kind = "OP"
        elif text.startswith('"') or text.startswith("'"):
            kind = "STRING"

        if kind is None:
            raise ValueError(f"Unexpected character: {text}")

        tokens.append((kind, text))

    return tokens
