from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_start_end():
        start, end = None, None
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 'S':
                    start = (r, c)
                elif grid[r][c] == 'E':
                    end = (r, c)
        return start, end

    start, end = get_start_end()
    if not start or not end:
        return -1

    def is_valid_move(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] != '#'

    def slide_from(r, c):
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            while is_valid_move(nr, nc):
                nr += dr
                nc += dc
            yield (nr - dr, nc - dc)

    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        (r, c), steps = queue.popleft()
        if (r, c) == end:
            return steps
        for new_r, new_c in slide_from(r, c):
            if (new_r, new_c) not in visited:
                visited.add((new_r, new_c))
                queue.append(((new_r, new_c), steps + 1))

    return -1
