def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]
    rings = (min(n, m) // 2 for n, m in [(n, n), (n - 1, n - 1)])

    for r in range(rings):
        top, bottom = r, n - r - 1
        left, right = r, n - r - 1

        # Extract the current ring
        ring = []
        for i in range(left, right + 1):
            ring.append(result[top][i])
        for i in range(top + 1, bottom + 1):
            ring.append(result[i][right])
        for i in range(right - 1, left - 1, -1):
            ring.append(result[bottom][i])
        for i in range(bottom - 1, top, -1):
            ring.append(result[i][left])

        # Rotate the ring
        k %= len(ring)
        if k < 0:
            k += len(ring)
        ring = ring[-k:] + ring[:-k]

        # Place the rotated ring back into the result matrix
        idx = 0
        for i in range(left, right + 1):
            result[top][i] = ring[idx]
            idx += 1
        for i in range(top + 1, bottom + 1):
            result[i][right] = ring[idx]
            idx += 1
        for i in range(right - 1, left - 1, -1):
            result[bottom][i] = ring[idx]
            idx += 1
        for i in range(bottom - 1, top, -1):
            result[i][left] = ring[idx]
            idx += 1

    return result

