def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program) and max_instructions > 0:
        max_instructions -= 1
        parts = program[ip].split()
        instruction = parts[0]

        if instruction == 'PUSH':
            stack.append(int(parts[1]))
        elif instruction == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif instruction == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Not enough elements for swap")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == 'ADD':
            if len(stack) < 2:
                raise ValueError("Not enough elements for addition")
            stack.append(stack.pop() + stack.pop())
        elif instruction == 'SUB':
            if len(stack) < 2:
                raise ValueError("Not enough elements for subtraction")
            stack.append(-stack.pop() + stack.pop())
        elif instruction == 'MUL':
            if len(stack) < 2:
                raise ValueError("Not enough elements for multiplication")
            stack.append(stack.pop() * stack.pop())
        elif instruction == 'JMP':
            try:
                ip = int(parts[1])
            except ValueError:
                raise ValueError("Invalid jump target")
        elif instruction == 'JZ':
            if not stack:
                raise ValueError("Stack underflow")
            if stack[-1] == 0:
                try:
                    ip = int(parts[1])
                except ValueError:
                    raise ValueError("Invalid jump target")
            else:
                ip += 1
        elif instruction == 'HALT':
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")

        ip += 1

    if max_instructions == 0:
        raise RuntimeError("Program exceeded maximum number of instructions")

    return stack[::-1]
