from collections import defaultdict

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting = defaultdict(list)

    for kind, item, quantity in events:
        if kind == 'receive':
            while waiting[item] and waiting[item][0][1] <= quantity:
                _, w_quantity = waiting[item].pop(0)
                quantity -= w_quantity
            if quantity > 0:
                waiting[item].append((item, quantity))
        elif kind == 'order':
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting[item].append((item, quantity))

    # Remove items with zero stock from the result
    stock_dict = {item: stock for item, stock in stock.items() if stock > 0}

    # Flatten the waiting list
    waiting_list = [order for sublist in waiting.values() for order in sublist]

    return stock_dict, waiting_list
