def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program):
        if max_instructions <= 0:
            raise RuntimeError("Too many instructions executed")

        instruction = program[ip].split()
        op = instruction[0]

        if op == 'PUSH':
            n = int(instruction[1])
            stack.append(n)
        elif op == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif op == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Not enough elements for swap")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                raise ValueError("Not enough elements for addition")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif op == 'SUB':
            if len(stack) < 2:
                raise ValueError("Not enough elements for subtraction")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif op == 'MUL':
            if len(stack) < 2:
                raise ValueError("Not enough elements for multiplication")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif op == 'JMP':
            try:
                t = int(instruction[1])
                if t < 0 or t >= len(program):
                    raise ValueError("Invalid jump target")
                ip = t
                continue
            except IndexError:
                pass
        elif op == 'JZ':
            if len(stack) < 1:
                raise ValueError("Not enough elements for conditional jump")
            n = stack.pop()
            if n == 0:
                try:
                    t = int(instruction[1])
                    if t < 0 or t >= len(program):
                        raise ValueError("Invalid jump target")
                    ip = t
                    continue
                except IndexError:
                    pass
        elif op == 'HALT':
            break
        else:
            raise ValueError(f"Unknown instruction: {op}")

        ip += 1
        max_instructions -= 1

    return stack[::-1]
