            if check_account(source) and check_account(target) and check_amount(amount) and not check_frozen(source) and not check_frozen(target) and source != target and final_balances[source] >= amount + 2:
                final_balances[source] -= amount + 2
                final_balances[target] += amount
            else:
                failed.append(i)
